kit.scene('boast', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'boast', back: '<g style="opacity:.28">' + W.lace(40, 120, 40, 980, 18, 7) + W.lace(878, 120, 878, 980, 18, 7) + '</g>',
      cast: [{ who: 'ravana', x: 560, y: 1730, s: 1.36 }],
      cam: [1.0, 1.045, 459, 520, 470, 500],
      arm: (t, i, talk) => 30 + 8 * Math.sin(t * 1.2),
      lines: [[4.2, 5.3, 'इसे पहनकर', 0, 0], [5.9, 7.95, 'देवराज इंद्र भी मेरे सामने टिक नहीं सकता।', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
